{"path":"marketing-capture/slugify.ts","content":"export function slugify(input: string): string {
  return input
    .toLowerCase()
    .trim()
    .replace(/\s+/g, '-')       // collapse whitespace to single hyphens
    .replace(/[^a-z0-9-]/g, ''); // strip characters outside [a-z0-9-]
}"}

{"content":"import { test } from 'node:test';
import assert from 'node:assert';
import { slugify } from './slugify.js';

test('slugify converts "Hello World" to "hello-world"', () => {
  assert.strictEqual(slugify('Hello World'), 'hello-world');
});

test('slugify handles leading/trailing spaces', () => {
  assert.strictEqual(slugify('  hello world  '), 'hello-world');
});

test('slugify strips punctuation', () => {
  assert.strictEqual(slugify('Foo Bar!'), 'foo-bar');
});","path":"marketing-capture/slugify.test.ts"}

